t.script:
document.addEventListener('DOMContentLoaded', function() {
    const voterInput = document.getElementById('voter-code');
    const btnSubmit = document.getElementById('btn-submit');
    const confirmModal = document.getElementById('confirm-modal');
    const btnCancel = document.getElementById('btn-modal-cancel');
    const btnConfirm = document.getElementById('btn-modal-confirm');
    const validationError = document.getElementById('validation-error');

    const votingCard = document.getElementById('voting-card');
    const successCard = document.getElementById('success-card');
    const successMessage = document.getElementById('success-message');
    const modalCandName = document.getElementById('modal-cand-name');

    const electionId = ;
    const positionId = ;
    const winnersCount = ;

    const candidateCards = document.querySelectorAll('.candidate-option-card');

    function updateSubmitButtonState() {
        const checkedCount = getSelectedCandidateIds().length;
        const codeLength = voterInput ? voterInput.value.length : 0;
        if (checkedCount > 0 && codeLength === 6) {
            btnSubmit.disabled = false;
        } else {
            btnSubmit.disabled = true;
        }
    }

    function getSelectedCandidateIds() {
        const ids = [];
        candidateCards.forEach(card => {
            const input = card.querySelector('input');
            if (input && input.checked) {
                ids.push(parseInt(input.value, 10));
            }
        });
        return ids;
    }

    function getSelectedCandidateNames() {
        const names = [];
        candidateCards.forEach(card => {
            const input = card.querySelector('input');
            if (input && input.checked) {
                names.push(card.dataset.candidateName);
            }
        });
        return names;
    }

    candidateCards.forEach(card => {
        const input = card.querySelector('input');
        if (!input) return;

        // Click on card
        card.addEventListener('click', function(e) {
            if (e.target.tagName === 'INPUT') {
                handleInputToggle(input, card);
                return;
            }

            input.checked = !input.checked;
            handleInputToggle(input, card);
        });
    });

    function handleInputToggle(input, card) {
        if (winnersCount === 1) {
            if (input.checked) {
                // Unselect all other cards
                candidateCards.forEach(c => {
                    if (c !== card) {
                        c.classList.remove('selected');
                        const otherInput = c.querySelector('input');
                        if (otherInput) otherInput.checked = false;
                    }
                });
                card.classList.add('selected');
            } else {
                card.classList.remove('selected');
            }
        } else {
            const checkedCount = getSelectedCandidateIds().length;
            if (checkedCount > winnersCount) {
                // Exceeded winners_count, revert check
                input.checked = false;
                alert(`Solo puedes elegir hasta ${winnersCount} candidatos.`);
            } else {
                if (input.checked) {
                    card.classList.add('selected');
                } else {
                    card.classList.remove('selected');
                }
            }
        }
        updateSubmitButtonState();
    }

    if (voterInput) {
        // Form validation
        voterInput.addEventListener('input', function() {
            this.value = this.value.replace(/[^0-9]/g, '');
            updateSubmitButtonState();
            validationError.classList.add('d-none');
        });

        // Trigger submit on enter
        voterInput.addEventListener('keypress', function(e) {
            if (e.key === 'Enter' && !btnSubmit.disabled) {
                e.preventDefault();
                btnSubmit.click();
            }
        });
    }

    // Open confirmation modal
    btnSubmit.addEventListener('click', function() {
        const names = getSelectedCandidateNames();
        modalCandName.textContent = names.join(', ');
        confirmModal.classList.add('active');
    });

    // Close modal
    btnCancel.addEventListener('click', function() {
        confirmModal.classList.remove('active');
    });

    // Submit vote
    btnConfirm.addEventListener('click', function() {
        const voterCode = voterInput.value;
        const selectedIds = getSelectedCandidateIds();

        btnConfirm.disabled = true;
        btnCancel.disabled = true;
        btnConfirm.innerHTML = 'Enviando...';

        // Call backend JSON route
        fetch(`/cdb/elections/${electionId}/vote/position/${positionId}/submit`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                params: {
                    voter_code: voterCode,
                    candidate_ids: selectedIds
                }
            })
        })
        .then(response => response.json())
        .then(data => {
            confirmModal.classList.remove('active');

            btnConfirm.disabled = false;
            btnCancel.disabled = false;
            btnConfirm.innerHTML = 'Confirmar Voto';

            const result = data.result;
            if (result && result.success) {
                successMessage.textContent = result.message;
                votingCard.classList.add('d-none');
                successCard.classList.remove('d-none');
            } else {
                validationError.textContent = result ? result.message : 'Error al registrar el voto.';
                validationError.classList.remove('d-none');
            }
        })
        .catch(err => {
            console.error(err);
            confirmModal.classList.remove('active');

            btnConfirm.disabled = false;
            btnCancel.disabled = false;
            btnConfirm.innerHTML = 'Confirmar Voto';

            validationError.textContent = 'Error de conexión. Intente nuevamente.';
            validationError.classList.remove('d-none');
        });
    });
});
